const unique=people=>[...new Map(people.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string').map(p=>[p.id,p])).values()];
export function producersOf(song){return unique(song.producers?.length?song.producers:[{id:song.producerId||song.producer,name:song.producer,aliases:song.producerAliases||[]}]);}
export function vocalistsOf(song){return unique(song.vocalists?.length?song.vocalists:(song.singers||[]).map(name=>({id:name,name,aliases:[]})));}
export function comparePeople(guess,answer){const a=unique(guess),b=new Set(unique(answer).map(p=>p.id)),tags=a.map(p=>({...p,status:b.has(p.id)?'exact':'wrong'})),matched=tags.filter(p=>p.status==='exact').length;return{status:matched===a.length&&a.length===b.size?'exact':matched?'close':'wrong',tags};}
const escape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function peopleText(song){return producersOf(song).map(p=>p.name).join(' / ')+' · '+vocalistsOf(song).map(p=>p.name).join(' / ');}
export function personTags(people){return'<span class="person-tags">'+unique(people).map(p=>'<span class="person-tag '+(p.status==='exact'?'matched':p.status==='wrong'?'unmatched':'neutral')+'"'+(p.status?' aria-label="'+escape(p.name+'，'+(p.status==='exact'?'匹配':'不匹配'))+'"':'')+'>'+(p.status==='exact'?'<span aria-hidden="true">✓ </span>':'')+escape(p.name)+'</span>').join('')+'</span>';}
export function peopleCell(result){const matched=result.tags.filter(p=>p.status==='exact').length,note=result.status==='exact'?'✓ 全部匹配':matched?matched+' / '+result.tags.length+' 位匹配 · 组合不同':'× 无重合';return'<td class="people-cell" aria-label="'+escape(result.tags.map(p=>p.name+'，'+(p.status==='exact'?'匹配':'不匹配')).join('；')+'；'+note)+'">'+personTags(result.tags)+'<span class="cell-note '+result.status+'">'+note+'</span></td>';}
